function twoSum(nums: number[], target: number): number[] {
    let hash: { [key: number]: number } = {};
    for (let i = 0; i < nums.length; i++) {
        let diff = target - nums[i];
        if (diff in hash) {
            return [hash[diff], i];
        } else {
            hash[nums[i]] = i;
        }
    }
}

