function addTwoNumbers(
    l1: ListNode | null,
    l2: ListNode | null,
): ListNode | null {
    let dummyNode: ListNode = new ListNode();
    let currentNode: ListNode = dummyNode;
    let carry: number = 0;

    while (l1 !== null || l2 !== null || carry !== 0) {
        const val1 = l1 !== null ? l1.val : 0;
        const val2 = l2 !== null ? l2.val : 0;

        const sum: number = val1 + val2 + carry;
        const value: number = sum % 10;
        const newLinkedList: ListNode = new ListNode(value);
        currentNode.next = newLinkedList;
        currentNode = newLinkedList;
        carry = Math.floor(sum / 10);

        l1 = l1 !== null ? l1.next : null;
        l2 = l2 !== null ? l2.next : null;
    }

    return dummyNode.next;
}

function lengthOfLongestSubstring(s: string): number {
    const charSet = new Set();
    let l = 0;
    let res = 0;

    for (let r = 0; r < s.length; r++) {
        while (charSet.has(s[r])) {
            charSet.delete(s[l]);
            l += 1;
        }
        charSet.add(s[r]);
        res = Math.max(res, r - l + 1);
    }
    return res;
}

function findMedianSortedArrays(nums1: number[], nums2: number[]): number {
    if (nums2.length < nums1.length) {
        [nums1, nums2] = [nums2, nums1];
    }

    let [left, right] = [0, nums1.length - 1];
    const totalLength = nums1.length + nums2.length;
    const mid = totalLength >> 1;
    const isEven = totalLength % 2 === 0;

    while (true) {
        const mid1 = left + right;
        const mid2 = mid - mid1 - 2;

        const getLeft = (nums, index) => (0 <= index ? nums[index] : -Infinity);
        const getRight = (nums, index) =>
            index + 1 < nums.length ? nums[index + 1] : Infinity;
        const [aLeft, bLeft] = [getLeft(nums1, mid1), getLeft(nums2, mid2)];
        const [aRight, bRight] = [getRight(nums1, mid1), getRight(nums2, mid2)];

        if (aLeft <= bRight && bLeft <= aRight) {
            return isEven
                ? (Math.max(aLeft, bLeft) + Math.min(aRight, bRight)) / 2
                : Math.min(aRight, bRight);
        }

        if (aLeft <= bRight) {
            left = mid1 + 1;
        }

        if (bRight < aLeft) {
            right = mid1 - 1;
        }
    }
}

function longestPalindrome(s: string): string {
    let res = '';
    let resLen = 0;

    for (let i = 0; i < s.length; i++) {
        let l = i;
        let r = i;

        while (l >= 0 && r < s.length && s[l] === s[r]) {
            if (r - l + 1 > resLen) {
                res = s.slice(l, r + 1);
                resLen = r - l + 1;
            }

            l -= 1;
            r += 1;
        }

        l = i;
        r = i + 1;

        while (l >= 0 && r < s.length && s[l] === s[r]) {
            if (r - l + 1 > resLen) {
                res = s.slice(l, r + 1);
                resLen = r - l + 1;
            }

            l -= 1;
            r += 1;
        }
    }

    return res;
}

const reverse = (x: number): number => {
    const max: number = 2 ** 31 - 1;
    const min: number = -(2 ** 31);

    let result: number = 0;
    while (x !== 0) {
        const digit = x % 10;
        x = Math.trunc(x / 10);

        if (result > max / 10 || (result === max / 10 && digit >= max % 10)) {
            return 0;
        } else if (
            result < min / 10 ||
            (result === max / 10 && digit <= min % 10)
        ) {
            return 0;
        } else {
            result = result * 10 + digit;
        }
    }

    return result;
};

