function isMatch(s: string, p: string): boolean {
    let lenS = s.length;
    let lenP = p.length;
    let map = {};

    return check(0, 0);

    function check(idxS: number, idxP: number): boolean {
        if (map[idxS + ':' + idxP] !== undefined) {
            return map[idxS + ':' + idxP];
        }

        if (idxS > lenS) {
            return false;
        }

        if (idxS === lenS && idxP === lenP) {
            return true;
        }

        if (p[idxP] === '.' || p[idxP] === s[idxS]) {
            map[idxS + ':' + idxP] =
                p[idxP + 1] === '*'
                    ? check(idxS + 1, idxP) || check(idxS, idxP + 2)
                    : check(idxS + 1, idxP + 1);
        } else {
            map[idxS + ':' + idxP] =
                p[idxP + 1] === '*' ? check(idxS, idxP + 2) : false;
        }

        return map[idxS + ':' + idxP];
    }
}

function maxArea(height: number[]): number {
    let l = 0;
    let r = height.length - 1;
    let max = 0;

    while (l < r) {
        let area = (r - l) * Math.min(height[l], height[r]);

        max = Math.max(max, area);

        if (height[l] < height[r]) {
            l += 1;
        } else {
            r -= 1;
        }
    }

    return max;
}

function intToRoman(num: number): string {
    const map = {
        M: 1000,
        CM: 900,
        D: 500,
        CD: 400,
        C: 100,
        XC: 90,
        L: 50,
        XL: 40,
        X: 10,
        IX: 9,
        V: 5,
        IV: 4,
        I: 1,
    };

    let result = '';

    for (let key in map) {
        const repeatCounter = Math.floor(num / map[key]);

        if (repeatCounter !== 0) result += key.repeat(repeatCounter);

        num %= map[key];

        if (num == 0) return result;
    }

    return result;
}

function romanToInt(s: string): number {
    let roman = {
        I: 1,
        V: 5,
        X: 10,
        L: 50,
        C: 100,
        D: 500,
        M: 1000,
    };

    let result = 0;

    for (let i = 0; i < s.length; i++) {
        if (i + 1 < s.length && roman[s[i]] < roman[s[i + 1]]) {
            result -= roman[s[i]];
        } else {
            result += roman[s[i]];
        }
    }

    return result;
}

