    for (let i = 0; i < strs[0].length; i++) {
        for (const s of strs) {
            if (i == s.length || s[i] !== strs[0][i]) {
                return res;
            }
        }
        res += strs[0][i];
    }

    return res;
}

function threeSum(nums: number[]): number[][] {
    const res: number[][] = [];
    nums = nums.sort((a, b) => a - b);

    for (let i = 0; i < nums.length; i++) {
        if (i > 0 && nums[i] == nums[i - 1]) {
            continue;
        }

        let l = i + 1;
        let r = nums.length - 1;
        while (l < r) {
            let sum = nums[i] + nums[l] + nums[r];

            if (sum > 0) {
                r -= 1;
            } else if (sum < 0) {
                l += 1;
            } else {
                res.push([nums[i], nums[l], nums[r]]);
                l += 1;
                while (nums[l] == nums[l - 1] && l < r) {
                    l += 1;
                }
            }
        }
    }
    return res;
}

function letterCombinations(digits: string): string[] {
    let res: string[] = [];

    const digitToChar = {
        '2': 'abc',
        '3': 'def',
        '4': 'ghi',
        '5': 'jkl',
        '6': 'mno',
        '7': 'qprs',
        '8': 'tuv',
        '9': 'wxyz',
    };

    function backtrack(i: number, curStr: string) {
        if (curStr.length === digits.length) {
            res.push(curStr);
            return;
        }

        for (const c of digitToChar[digits[i]]) {
            backtrack(i + 1, curStr + c);
        }
    }

    if (digits) {
        backtrack(0, '');
    }

    return res;
}

function fourSum(nums: number[], target: number): number[][] {
    const sortedNums: number[] = nums.sort((a: number, b: number) => a - b);
    const res: number[][] = [];
    const quad: number[] = [];

    const kSum = (k: number, start: number, target: number): void => {
        if (k > 2) {
            for (let i = start; i < sortedNums.length; i++) {
                if (i !== start && sortedNums[i] === sortedNums[i - 1]) {
                    continue;
                }
                quad.push(sortedNums[i]);
                kSum(k - 1, i + 1, target - sortedNums[i]);
                quad.pop();
            }
        } else {
            let left: number = start;
            let right: number = sortedNums.length - 1;

            while (left < right) {
                const sum = sortedNums[left] + sortedNums[right];
                if (sum < target) {
                    left++;
                } else if (sum > target) {
                    right--;
                } else {
                    res.push(
                        quad.concat([sortedNums[left], sortedNums[right]]),
                    );
                    left++;
                    while (
                        left < right &&
                        sortedNums[left] === sortedNums[left - 1]
                    ) {
                        left++;
                    }
                }
            }
        }
    };
    kSum(4, 0, target);
    return res;
}

