function search(nums: number[], target: number): number {
    let left: number = 0;
    let right: number = nums.length - 1;

    while (left <= right) {
        let midIdx: number = Math.floor((left + right) / 2);
        if (nums[midIdx] === target) return midIdx;

        if (nums[left] <= nums[midIdx]) {
            if (nums[left] <= target && target <= nums[midIdx])
                right = midIdx - 1;
            else left = midIdx + 1;
        } else {
            if (nums[midIdx] <= target && target <= nums[right])
                left = midIdx + 1;
            else right = midIdx - 1;
        }
    }
    return -1;
}

function searchInsert(nums: number[], target: number): number {
    let [left, right] = [0, nums.length - 1];

    while (left <= right) {
        const middle = Math.floor((left + right) / 2);
        if (nums[middle] == target) {
            return middle;
        } else if (nums[middle] < target) {
            left = middle + 1;
        } else {
            right = middle - 1;
        }
    }

    return left;
}

function isValidSudoku(board: string[][]): boolean {
    const rows = {};
    const cols = {};
    const squares = {};

    for (let r = 0; r < 9; r++) {
        for (let c = 0; c < 9; c++) {
            const num = board[r][c];

            if (num === '.') {
                continue;
            }

            const grid = `${Math.floor(r / 3)}${Math.floor(c / 3)}`;

            if (!cols[c]) {
                cols[c] = new Set();
            }
            if (!rows[r]) {
                rows[r] = new Set();
            }
            if (!squares[grid]) {
                squares[grid] = new Set();
            }

            if (
                rows[r].has(num) ||
                cols[c].has(num) ||
                squares[grid].has(num)
            ) {
                return false;
            }

            cols[c].add(num);
            rows[r].add(num);
            squares[grid].add(num);
        }
    }

    return true;
}

function combinationSum(candidates: number[], target: number): number[][] {
    let res: number[][] = [];

    function dfs(i: number, cur: number[], total: number) {
        if (total == target) {
            res.push(cur.slice());
            return;
        }
        if (i >= candidates.length || total > target) {
            return;
        }

        cur.push(candidates[i]);
        dfs(i, cur, total + candidates[i]);

        cur.pop();
        dfs(i + 1, cur, total);
    }

    dfs(0, [], 0);

    return res;
}

function combinationSum2(candidates: number[], target: number): number[][] {
    candidates.sort();

    const res: number[][] = [];

    function backtrack(cur: number[], pos: number, target: number) {
        if (target === 0) {
            res.push(cur.slice());
        }
        if (target <= 0) {
            return;
        }
        let prev = -1;

        for (let i = pos; i < candidates.length; i++) {
            if (candidates[i] == prev) {
                continue;
            }

            cur.push(candidates[i]);

            backtrack(cur, i + 1, target - candidates[i]);

            cur.pop();
            prev = candidates[i];
        }
    }

    backtrack([], 0, target);

    return res;
}

function firstMissingPositive(nums: number[]): number {
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] < 0) {
            nums[i] = 0;
        }
    }

    for (let i = 0; i < nums.length; i++) {
        let val = Math.abs(nums[i]);
        if (1 <= val && val <= nums.length) {
            if (nums[val - 1] > 0) {
                nums[val - 1] *= -1;
            } else if (nums[val - 1] === 0) {
                nums[val - 1] = -1 * (nums.length + 1);
            }
        }
    }

    for (let i = 1; i < nums.length + 1; i++) {
        if (nums[i - 1] >= 0) {
            return i;
        }
    }

    return nums.length + 1;
}

function trap(height: number[]): number {
    if (!height) return 0;

    let l = 0;
    let r = height.length - 1;
    let leftMax = height[l];
    let rightMax = height[r];
    let res = 0;

    while (l < r) {
        if (leftMax < rightMax) {
            l += 1;
            leftMax = Math.max(leftMax, height[l]);
            res += leftMax - height[l];
        } else {
            r -= 1;
            rightMax = Math.max(rightMax, height[r]);
            res += rightMax - height[r];
        }
    }

    return res;
}

function multiply(num1: string, num2: string): string {
    if (num1 === '0' || num2 === '0') {
        return '0';
    }

    let maxLength: number = num1.length + num2.length;
    let result: Array<number> = Array(maxLength).fill(0);
    for (let i = num2.length - 1; i >= 0; i--) {
        let idx = maxLength - (num2.length - i);

        for (let j = num1.length - 1; j >= 0; j--) {
            const product =
                result[idx] +
                parseInt(num1.charAt(j)) * parseInt(num2.charAt(i));
            result[idx] = Math.floor(product % 10);
            result[idx - 1] = Math.floor(product / 10) + result[idx - 1];
            idx--;
        }
    }
    if (result[0] === 0) return result.slice(1).join('');
    else return result.join('');
}

function jump(nums: number[]): number {
    let left = 0;
    let right = 0;
    let res = 0;

    while (right < nums.length - 1) {
        let maxJump = 0;
        for (let i = left; i <= right; i++) {
            maxJump = Math.max(maxJump, i + nums[i]);
        }
        left = right + 1;
        right = maxJump;
        res += 1;
    }
    return res;
}

function permute(nums: number[]): number[][] {
    const res: number[][] = [];

    if (nums.length === 1) {
        return [nums.slice()];
    }

    for (const i of nums) {
        let n = nums.shift()!;

        let perms = permute(nums);

        for (const perm of perms) {
            perm.push(n);
        }

        perms.forEach((perm) => {
            res.push(perm);
        });

        nums.push(n);
    }

    return res;
}

function permuteUnique(nums: number[]): number[][] {
    const results: number[][] = [];
    const numsCount = new Map();
    for (let n of nums) {
        numsCount.set(n, (numsCount.get(n) ?? 0) + 1);
    }

    function traverse(sequence: number[] = []) {
        if (sequence.length === nums.length) {
            results.push([...sequence]);
            return;
        }

        for (let [n, count] of numsCount) {
            if (count === 0) continue;

            numsCount.set(n, count - 1);
            sequence.push(n);
            traverse(sequence);
            sequence.pop();
            numsCount.set(n, count);
        }
    }
    traverse();

    return results;
}

function rotate(matrix: number[][]): void {
    let l = 0;
    let r = matrix.length - 1;

    while (l < r) {
        for (let i = 0; i < r - l; i++) {
            let top = l;
            let bottom = r;

            let topLeft = matrix[top][l + i];

            matrix[top][l + i] = matrix[bottom - i][l];
            matrix[bottom - i][l] = matrix[bottom][r - i];
            matrix[bottom][r - i] = matrix[top + i][r];
            matrix[top + i][r] = topLeft;
        }
        r -= 1;
        l += 1;
    }
}

function groupAnagrams(strs: string[]): string[][] {
    const hash: {
