    //explore starting from empty state
    searchRec(start, n, solutions);

    return solutions;
}

function maxSubArray(nums: number[]): number {
    let maxSub = nums[0];
    let curSum = 0;

    for (const n of nums) {
        if (curSum < 0) {
            curSum = 0;
        }
        curSum += n;
        maxSub = Math.max(maxSub, curSum);
    }

    return maxSub;
}

function spiralOrder(matrix: number[][]): number[] {
    const res: number[] = [];
    let left = 0;
    let right = matrix[0].length;
    let top = 0;
    let bottom = matrix.length;

    while (left < right && top < bottom) {
        // get every i in the top row
        for (let i = left; i < right; i++) {
            res.push(matrix[top][i]);
        }
        top += 1;

        // get every i in the right column
        for (let i = top; i < bottom; i++) {
            res.push(matrix[i][right - 1]);
        }
        right -= 1;

        if (!(left < right && top < bottom)) {
            break;
        }

        // get ever i in the bottom row
        for (let i = right - 1; i > left - 1; i--) {
            res.push(matrix[bottom - 1][i]);
        }
        bottom -= 1;

        // get evet i in the left column
        for (let i = bottom - 1; i > top - 1; i--) {
            res.push(matrix[i][left]);
        }
        left += 1;
    }

    return res;
}

function canJump(nums: number[]): boolean {
    let goal = nums.length - 1;

    for (let i = nums.length - 2; i >= 0; i--) {
        if (i + nums[i] >= goal) {
            goal = i;
        }
    }
    return goal == 0;
}

function merge(intervals: number[][]): number[][] {
    intervals.sort(([aStart, aEnd], [bStart, bEnd]) =>
        aStart !== bStart ? aStart - bStart : aEnd - bEnd,
    );

    return mergeInterval(intervals);
}

function mergeInterval(intervals: number[][]): number[][] {
    let merged = [];
    let prev = intervals.shift();

    for (const curr of intervals) {
        const [prevStart, prevEnd] = prev;
        const [currStart, currEnd] = curr;

        // Overlap occurs
        if (currStart <= prevEnd) {
            prev[1] = Math.max(prev[1], curr[1]);
            continue;
        }

        merged.push(prev);
        prev = curr;
    }
    return [...merged, prev];
}

function insert(intervals: number[][], newInterval: number[]): number[][] {
    const { beforeIndex, before } = getBefore(intervals, newInterval);
    const afterIndex = mergeIntervals(intervals, newInterval, beforeIndex);
    const after = intervals.slice(afterIndex);

    return [...before, newInterval, ...after];
}

const getBefore = (intervals, newInterval, index = 0, before = []) => {
    const hasGap = ([prevStart, prevEnd], [currStart, currEnd]) =>
        prevEnd < currStart;

    while (index < intervals.length && hasGap(intervals[index], newInterval)) {
        const current = intervals[index];
        before.push(current);
        index++;
    }
    return { beforeIndex: index, before };
};

const mergeIntervals = (intervals, newInterval, index) => {
    const hasOverlap = ([prevStart, prevEnd], [currStart, currEnd]) =>
        currStart <= prevEnd;

    while (
        index < intervals.length &&
        hasOverlap(newInterval, intervals[index])
    ) {
        const current = intervals[index];
        newInterval[0] = Math.min(newInterval[0], current[0]);
        newInterval[1] = Math.max(newInterval[1], current[1]);
        index++;
    }
    return index;
};

