function setZeroes(matrix: number[][]): void {
    let row = new Array(matrix.length);
    let col = new Array(matrix[0].length);

    for (let i = 0; i < row.length; i++) {
        for (let j = 0; j < col.length; j++) {
            if (matrix[i][j] === 0) {
                row[i] = 0;
                col[j] = 0;
            }
        }
    }

    for (let i = 0; i < row.length; i++) {
        for (let j = 0; j < col.length; j++) {
            if (row[i] == 0 || col[j] == 0) {
                matrix[i][j] = 0;
            }
        }
    }
}

function searchMatrix(matrix: number[][], target: number): boolean {
    const rows = matrix.length;
    const columns = matrix[0].length;

    let top = 0;
    let bot = rows - 1;

    while (top <= bot) {
        let row = Math.floor((top + bot) / 2);
        if (target > matrix[row][columns - 1]) {
            top = row + 1;
        } else if (target < matrix[row][0]) {
            bot = row - 1;
        } else {
            break;
        }
    }

    if (top > bot) {
        return false;
    }

    let row = Math.floor((top + bot) / 2);
    let l = 0;
    let r = columns - 1;

    while (l <= r) {
        let m = Math.floor((l + r) / 2);
        if (target > matrix[row][m]) {
            l = m + 1;
        } else if (target < matrix[row][m]) {
            r = m - 1;
        } else {
            return true;
        }
    }

    return false;
}

/**
 Do not return anything, modify nums in-place instead.
 */
function sortColors(nums: number[]): void {
    let l = 0;
    let r = nums.length - 1;
    let i = 0;

    function swap(a: number, b: number) {
        let temp = nums[a];
        nums[a] = nums[b];
        nums[b] = temp;
    }

    while (i <= r) {
        if (nums[i] == 0) {
            swap(l, i);
            l += 1;
        } else if (nums[i] == 2) {
            swap(r, i);
            r -= 1;
            i -= 1;
        }
        i += 1;
    }
}

function minWindow(s: string, t: string): string {
    let minL = 0;
    let minR = s.length;

    //create string t hashmap and needed
    const tCount = {};
    let needed = 0;
    for (let i = 0; i < t.length; i++) {
        if (t[i] in tCount) tCount[t[i]]++;
        else {
            tCount[t[i]] = 1;
            needed++;
        }
    }

    //initialize winCount(empty)
    const winCount = {};
    let matched = 0;

    let l = 0;

    for (let r = 0; r < s.length; r++) {
        //update winCount with adding s[r]
        if (s[r] in winCount) winCount[s[r]]++;
        else winCount[s[r]] = 1;
        //update matched
        if (s[r] in tCount && winCount[s[r]] === tCount[s[r]]) matched++;

        //the window is valid
        while (matched === needed) {
            //update min
            if (r - l + 1 < minR - minL + 1) {
                minL = l;
                minR = r;
            }

            //remove l
            //update matched
            if (s[l] in tCount && winCount[s[l]] === tCount[s[l]]) matched--;
            //update winCount with the removal of s[l]
            winCount[s[l]]--;
            if (winCount[s[l]] === 0) delete winCount[s[l]];
            l++;
        }
    }

    return minR - minL + 1 > s.length ? '' : s.slice(minL, minR + 1);
}

function subsets(nums: number[]): number[][] {
    let res: number[][] = [];
    let subset: number[] = [];
    function dfs(i: number) {
        if (i >= nums.length) {
            res.push(subset.slice());
            return;
        }

        subset.push(nums[i]);
        dfs(i + 1);

        subset.pop();
        dfs(i + 1);
    }

    dfs(0);

    return res;
}

function exist(board: string[][], word: string): boolean {
    const rowsLength = board.length;
    const colsLength = board[0].length;

    function outOfBounds(r: number, c: number) {
        return r < 0 || c < 0 || r >= rowsLength || c >= colsLength;
    }

    // idx: the index of the current character in the word we're looking for
    function dfs(row: number, col: number, idx: number): boolean {
        if (idx === word.length) {
            return true;
        }
        if (outOfBounds(row, col) || word[idx] !== board[row][col]) {
            return false;
        }

        // Mark the current cell as visited
        let currentCell = board[row][col];
        board[row][col] = '*';

        // Pass idx + 1 because we're looking for
        // the next character in the word now
        let result =
            dfs(row + 1, col, idx + 1) || // down
            dfs(row - 1, col, idx + 1) || // up
            dfs(row, col + 1, idx + 1) || // right
            dfs(row, col - 1, idx + 1); // left

        // Reset the current cell to its original value
        // because we're done visiting it
        board[row][col] = currentCell;

        return result;
    }

    // For each cell, do a depth-first search
    for (let i = 0; i < rowsLength; i++) {
        for (let j = 0; j < colsLength; j++) {
            if (dfs(i, j, 0)) {
                return true;
            }
        }
    }

    return false;
}

function largestRectangleArea(heights: number[]): number {
    let largestArea = 0;
    let stack = [];

    for (let i = 0; i < heights.length; i++) {
        let start = i;

        while (stack.length > 0 && stack[stack.length - 1][1] > heights[i]) {
            let [lastI, lastH] = stack.pop();
            largestArea = Math.max(largestArea, lastH * (i - lastI));
            start = lastI;
        }
        stack.push([start, heights[i]]);
    }

    for (let j = 0; j < stack.length; j++) {
        let currArea = stack[j][1] * (heights.length - stack[j][0]);
        largestArea = Math.max(largestArea, currArea);
    }

    return largestArea;
}

/**
 Do not return anything, modify nums1 in-place instead.
 */
function merge(nums1: number[], m: number, nums2: number[], n: number): void {
    let last = m + n - 1;

    while (m > 0 && n > 0) {
        if (nums1[m - 1] > nums2[n - 1]) {
            nums1[last] = nums1[m - 1];
            m -= 1;
        } else {
            nums1[last] = nums2[n - 1];
            n -= 1;
        }
        last -= 1;
    }

    while (n > 0) {
        nums1[last] = nums2[n - 1];
        n -= 1;
        last -= 1;
    }
}

function subsetsWithDup(nums: number[]): number[][] {
    let res: number[][] = [];
    nums.sort();

    function backtrack(i: number, subset: number[]) {
        if (i == nums.length) {
            res.push(subset.slice());
            return;
        }

        subset.push(nums[i]);
        backtrack(i + 1, subset);

        subset.pop();

        while (i + 1 < nums.length && nums[i] == nums[i + 1]) {
            i += 1;
        }

        backtrack(i + 1, subset);
    }

    backtrack(0, []);

    return res;
}

function numDecodings(s: string): number {
    let dp = {
        [s.length]: 1,
    };

    for (let i = s.length - 1; i > -1; i--) {
        if (s[i] == '0') {
            dp[i] = 0;
        } else {
            dp[i] = dp[i + 1];
        }
        if (
            i + 1 < s.length &&
            (s[i] == '1' || (s[i] == '2' && '0123456'.includes(s[i + 1])))
        ) {
            dp[i] += dp[i + 2];
        }
    }
    return dp[0];
}

function restoreIpAddresses(s: string): string[] {
    let result: string[] = [];

    if (s.length > 12) return result;

    function backtrack(i: number, dots: number, currentIP: string) {
        if (dots == 4 && i == s.length) {
            result.push(currentIP.slice(0, currentIP.length - 1));
            return;
        } else if (dots > 4) {
            return;
        }

        for (let j = i; j < Math.min(i + 3, s.length); j++) {
            if (parseInt(s.slice(i, j + 1)) < 256 && (i == j || s[i] != '0')) {
                backtrack(j + 1, dots + 1, currentIP + s.slice(i, j + 1) + '.');
            }
        }
    }

    backtrack(0, 0, '');

    return result;
}

/**
 * Definition for a binary tree node.
 * class TreeNode {
 *     val: number
 *     left: TreeNode | null
 *     right: TreeNode | null
 *     constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.left = (left===undefined ? null : left)
 *         this.right = (right===undefined ? null : right)
 *     }
 * }
 */
function inorderTraversal(
    root: TreeNode | null,
    list: Array<number> = [],
): number[] {
    if (!root) return [];

    inorderTraversal(root.left, list);
    list.push(root.val);
    inorderTraversal(root.right, list);

    return list;
}

function isInterleave(s1: string, s2: string, s3: string): boolean {
    const l1 = s1.length;
    const l2 = s2.length;
    const l3 = s3.length;

    if (l1 + l2 !== l3) {
        return false;
    }

    if (!s1 || !s2 || !s3) {
        return (!s1 && !s2 && !s3) || (s1 ? s1 === s3 : s2 === s3);
    }

    const seen = new Array(l2 + 1);
    seen[l2] = true;

    for (let i = l2 - 1; i >= 0; i--) {
        seen[i] = seen[i + 1] && s2[i] === s3[l1 + i];
    }

    for (let i = l1 - 1; i >= 0; i--) {
        for (let j = l2; j >= 0; j--) {
            seen[j] =
                (seen[j] && s1[i] === s3[i + j]) ||
                (j !== l2 && seen[j + 1] && s2[j] === s3[i + j]);
        }
    }
    return seen[0];
}

/**
 * Definition for a binary tree node.
 * class TreeNode {
 *     val: number
 *     left: TreeNode | null
 *     right: TreeNode | null
 *     constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.left = (left===undefined ? null : left)
 *         this.right = (right===undefined ? null : right)
 *     }
 * }
 */

function isValidBST(root: TreeNode | null): boolean {
    return validate(root, null, null);
}

function validate(
    root: TreeNode | null,
    max: number | null,
    min: number | null,
): boolean {
    if (!root) {
        return true;
    }

    if (
        (max !== null && root.val >= max) ||
        (min !== null && root.val <= min)
    ) {
        return false;
    }

    return (
        validate(root.left, root.val, min) &&
        validate(root.right, max, root.val)
    );
}

/**
 * Definition for a binary tree node.
 * class TreeNode {
 *     val: number
 *     left: TreeNode | null
 *     right: TreeNode | null
 *     constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.left = (left===undefined ? null : left)
 *         this.right = (right===undefined ? null : right)
 *     }
 * }
 */

function isSameTree(p: TreeNode | null, q: TreeNode | null): boolean {
    if (p === null && q === null) return true;

    if ((p === null && q !== null) || (p !== null && q === null)) return false;

    let leftSame = isSameTree(p.left, q.left);
    let rightSame = isSameTree(p.right, q.right);

    if (p.val === q.val && leftSame && rightSame) {
        return true;
    }

    return false;
}

/**
 * Definition for a binary tree node.
 * class TreeNode {
 *     val: number
 *     left: TreeNode | null
 *     right: TreeNode | null
 *     constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.left = (left===undefined ? null : left)
 *         this.right = (right===undefined ? null : right)
 *     }
 * }
 */

function levelOrder(root: TreeNode | null): number[][] {
    const levels: number[][] = [];

    function getHeight(node: TreeNode | null, height: number) {
        if (!node) return 0;

        if (node.left || node.right) {
            getHeight(node.left, height + 1);
            getHeight(node.right, height + 1);
        }

        if (levels[height]) {
            levels[height].push(node.val);
        } else {
            levels[height] = [node.val];
        }
    }

    getHeight(root, 0);

    return levels;
}

/**
 * Definition for a binary tree node.
 * class TreeNode {
 *     val: number
 *     left: TreeNode | null
 *     right: TreeNode | null
 *     constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.left = (left===undefined ? null : left)
 *         this.right = (right===undefined ? null : right)
 *     }
 * }
 */

function maxDepth(root: TreeNode | null): number {
    if (!root) return 0;

    return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));
}

/**
 * Definition for a binary tree node.
 * class TreeNode {
 *     val: number
 *     left: TreeNode | null
 *     right: TreeNode | null
 *     constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.left = (left===undefined ? null : left)
 *         this.right = (right===undefined ? null : right)
 *     }
 * }
 */

function buildTree(preorder: number[], inorder: number[]): TreeNode | null {
    if (!preorder.length || !inorder.length) {
        return null;
    }

    let root = new TreeNode(preorder[0]);
    let mid = inorder.indexOf(preorder[0]);

    root.left = buildTree(preorder.slice(1, mid + 1), inorder.slice(0, mid));
    root.right = buildTree(preorder.slice(mid + 1), inorder.slice(mid + 1));
    return root;
}

