function isBalanced(root: TreeNode | null): boolean {
    let array = getHeight(root);
    return array[0];
}

function getHeight(root: TreeNode | null) {
    if (!root) return [true, 0];

    let [leftBalanced, leftHeight] = getHeight(root.left);
    let [rightBalanced, rightHeight] = getHeight(root.right);

    let balanced =
        leftBalanced &&
        rightBalanced &&
        Math.abs(rightHeight - leftHeight) <= 1;

    return [balanced, 1 + Math.max(leftHeight, rightHeight)];
}

function numDistinct(s: string, t: string): number {
    const sLen = s.length;
    const tLen = t.length;

    if (sLen < tLen) {
        return 0;
    }

    const cache = new Array(tLen).fill(0);
    for (let r = sLen - 1; r >= 0; r--) {
        let prev = 1;
        for (let c = tLen - 1; c >= 0; c--) {
            const curr = cache[c];
            if (s[r] === t[c]) {
                cache[c] += prev;
            }
            prev = curr;
        }
    }
    return cache[0];
}

function generate(numRows: number): number[][] {
    let res = [[1]];

    for (let i = 0; i < numRows - 1; i++) {
        let temp = [0, ...res.at(-1), 0];
        let row = [];
        for (let j = 0; j < res.at(-1).length + 1; j++) {
            row.push(temp[j] + temp[j + 1]);
        }
        res.push(row);
    }
    return res;
}

function maxProfit(prices: number[]): number {
    let max = 0;
    let l = 0;
    let r = 1;

    while (r < prices.length) {
        if (prices[l] < prices[r]) {
            let profit = prices[r] - prices[l];
            if (profit > max) {
                max = profit;
            }
        } else {
            l = r;
        }
        r++;
    }

    return max;
}

