function maxPathSum(root: TreeNode | null): number {
    const res = [root.val];

    // return max path sum without split
    function dfs(root: TreeNode | null): number {
        if (!root) {
            return 0;
        }

        let leftMax = dfs(root.left);
        let rightMax = dfs(root.right);
        leftMax = Math.max(leftMax, 0);
        rightMax = Math.max(rightMax, 0);

        // compute max path sum WITH split
        res[0] = Math.max(res[0], root.val + leftMax + rightMax);
        return root.val + Math.max(leftMax, rightMax);
    }

    dfs(root);
    return res[0];
}

function isPalindrome(s: string): boolean {
    const array = s
        .toLowerCase()
        .replace(/[^A-Za-z0-9]/g, '')
        .replace(/\s/g, '')
        .split('');

    for (let i = 0; i < array.length; i++) {
        const first = array[i];
        const second = array[array.length - 1 - i];

        if (first !== second) {
            return false;
        }
    }
    return true;
}

function ladderLength(
    beginWord: string,
    endWord: string,
    wordList: string[],
): number {
    if (!wordList.includes(endWord)) {
        return 0;
    }
    let patternMap = {};
    wordList.push(beginWord);

    for (let word of wordList) {
        for (let x = 0; x < word.length; x++) {
            const pattern = word.slice(0, x) + '*' + word.slice(x + 1);
            patternMap[pattern] = patternMap[pattern] || [];
            patternMap[pattern].push(word);
        }
    }

    let wordCount = 1,
        queue = [beginWord],
        visited = [beginWord];
    while (queue.length) {
        const levelSize = queue.length;
        for (let x = 0; x < levelSize; x++) {
            const word = queue.shift();
            if (word === endWord) {
                return wordCount;
            }

            for (let x = 0; x < word.length; x++) {
                const pattern = word.slice(0, x) + '*' + word.slice(x + 1);
                for (let nei of patternMap[pattern]) {
                    if (nei in visited) {
                        continue;
                    }
                    visited[nei] = nei;
                    queue.push(nei);
                }
            }
        }
        wordCount++;
    }
    return 0;
}

function longestConsecutive(nums: number[]): number {
    const number = new Set(nums);
    let longest = 0;

    for (const n of nums) {
        if (!number.has(n - 1)) {
            let length = 0;
            while (number.has(n + length)) {
                length += 1;
            }
            longest = Math.max(length, longest);
        }
    }

    return longest;
}

/**
 Do not return anything, modify board in-place instead.
 */
function solve(board: string[][]): void {
    const rowLen = board.length;
    const colLen = board[0].length;
    const lastRow = rowLen - 1;
    const lastCol = colLen - 1;

    for (let r = 0; r < rowLen; ++r) {
        markSeen(r, 0);
        markSeen(r, lastCol);
    }
    for (let c = 1; c < lastCol; ++c) {
        markSeen(0, c);
        markSeen(lastRow, c);
    }

    for (let r = 0; r < rowLen; ++r) {
        for (let c = 0; c < colLen; ++c) {
            switch (board[r][c]) {
                case 'O':
                    board[r][c] = 'X';
                    break;
                case 'A':
                    board[r][c] = 'O';
                    break;
            }
        }
    }

    function markSeen(r: number, c: number): void {
        if (!inBounds(r, c) || board[r][c] !== 'O') {
            return;
        }

        board[r][c] = 'A';

        markSeen(r - 1, c);
        markSeen(r + 1, c);
        markSeen(r, c - 1);
        markSeen(r, c + 1);
    }

    function inBounds(r: number, c: number): boolean {
        return r >= 0 && c >= 0 && r < rowLen && c < colLen;
    }
}

function partition(s: string): string[][] {
    let res: string[][] = [];
    let part: string[] = [];

    function dfs(i: number) {
        if (i >= s.length) {
            res.push(part.slice());
            return;
        }

        for (let j = i; j < s.length; j++) {
            if (isPali(s, i, j)) {
                part.push(s.slice(i, j + 1));
                dfs(j + 1);
                part.pop();
            }
        }
    }

    dfs(0);
    return res;

    function isPali(s: string, l: number, r: number) {
        while (l < r) {
            if (s[l] != s[r]) {
                return false;
            }
            l = l + 1;
            r = r - 1;
        }
        return true;
    }
}

let dfs = (node: Node, memo: Map<Node, Node>) => {
    if (node === null) return null;

    //if this node has already been visited, simply return the counterpart node of the new graph and return
    if (memo.has(node)) return memo.get(node);

    //node hasn't been already visited, create its counterpart version for the new graph
    let newNode = new Node(node.val);
    //maps to the old graph counterpart(also marked as visited)
    memo.set(node, newNode);

    //for each edge of the old node, add that edge in the new graph node
    for (let i = 0; i < node.neighbors.length; i++) {
        newNode.neighbors.push(dfs(node.neighbors[i], memo));
    }

    return newNode;
};

function cloneGraph(node: Node | null): Node | null {
    //uses a map, maps old graph nodes with new graph ones
    //it also tells us which node of the old graph have already been visited
    let memo = new Map<Node, Node>();

    return dfs(node, memo);
}

function canCompleteCircuit(gas: number[], cost: number[]): number {
    let res = 0;
    let netDistance = 0;

    // Checks if there is enough gas to complete a cycle
    if (gas.reduce((a, b) => a + b) - cost.reduce((a, b) => a + b) < 0) {
        return -1;
    }

    // finds positive netDistance to check if cycle can be completed
    for (let i = 0; i < gas.length; i++) {
        netDistance += gas[i] - cost[i];

        // resets net Distance and gets gas starting gas station
        if (netDistance < 0) {
            netDistance = 0;
            res = i + 1;
        }
    }
    return res;
}

function singleNumber(nums: number[]): number {
