}

function copyRandomList(head: Node | null): Node | null {
    let hash = new Map<Node, Node>();

    let newHead = new Node(0);

    let itr = head;

    let itrN = newHead;

    while (itr !== null) {
        let newN = new Node(itr.val);
        itrN.next = newN;
        itrN = newN;
        hash.set(itr, newN);

        itr = itr.next;
    }

    itr = head;
    while (itr !== null) {
        let inNew = hash.get(itr);
        if (itr.random !== null) {
            let inNewRand = hash.get(itr.random);
            inNew.random = inNewRand;
        }
        itr = itr.next;
    }

    return newHead.next;
}

function wordBreak(s: string, wordDict: string[]): boolean {
    const dp = Array(s.length + 1).fill(false);

    dp[s.length] = true;

    for (let i = s.length - 1; i > -1; i--) {
        for (const w of wordDict) {
            if (i + w.length <= s.length && s.slice(i, i + w.length) == w) {
                dp[i] = dp[i + w.length];
            }
            if (dp[i]) {
                break;
            }
        }
    }

    return dp[0];
}

/**
 * Definition for singly-linked list.
 * class ListNode {
 *     val: number
 *     next: ListNode | null
 *     constructor(val?: number, next?: ListNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.next = (next===undefined ? null : next)
 *     }
 * }
 */

function hasCycle(head: ListNode | null): boolean {
    let slow = head;
    let fast = head;

    while (fast && fast.next) {
        if (slow) {
            slow = slow.next;
        }
        fast = fast.next.next;
        if (slow == fast) {
            return true;
        }
    }

    return false;
}

/**
 * Definition for singly-linked list.
 * class ListNode {
 *     val: number
 *     next: ListNode | null
 *     constructor(val?: number, next?: ListNode | null) {
 *         this.val = (val===undefined ? 0 : val)
 *         this.next = (next===undefined ? null : next)
 *     }
 * }
 */

/**
 Do not return anything, modify head in-place instead.
 */
function reorderList(head: ListNode | null): void {
    let slow: ListNode | null | undefined = head;
    let fast: ListNode | null | undefined = head?.next;

    while (fast && fast.next) {
        slow = slow?.next;
        fast = fast?.next?.next;
    }

    // reverse second half
    if (!(slow && slow.next)) return;
    let second: ListNode | null = slow.next;
    slow.next = null;
    let prev: ListNode | null = null;
    while (second) {
        let temp = second.next;
        second.next = prev;
        prev = second;
        second = temp;
    }

    // merge two halfs
    let first: any = head;
    second = prev;
    while (second) {
        let temp1 = first.next;
        let temp2 = second.next;
        first.next = second;
        second.next = temp1;
        first = temp1;
        second = temp2;
    }
}

