}

/**
 * Your LRUCache object will be instantiated and called as such:
 * var obj = new LRUCache(capacity)
 * var param_1 = obj.get(key)
 * obj.put(key,value)
 */

type CacheNode = {
    value: number;
    key: number | null;
    next: CacheNode | null;
    prev: CacheNode | null;
};

class LRUCache {
    private size: number;
    private capacity: number;
    private data: Map<number, CacheNode>;
    private head: CacheNode;
    private tail: CacheNode;

    constructor(capacity: number) {
        this.capacity = capacity;
        this.size = 0;

        this.data = new Map();
        // Initialize dummy nodes for convenience
        this.head = { value: 0 } as CacheNode;
        this.tail = { value: 0 } as CacheNode;

        this.head.next = this.tail;
        this.tail.prev = this.head;
    }

    get(key: number): number {
        const node = this.data.get(key);
        if (!node) return -1;

        node.prev.next = node.next;
        node.next.prev = node.prev;

        node.next = this.head.next;
        node.prev = this.head;

        this.head.next.prev = node;
        this.head.next = node;

        return node.value;
    }

    put(key: number, value: number): void {
        let node = this.data.get(key);
        if (!node) {
            this.size++;
            node = { value, key } as CacheNode;
            this.data.set(key, node);
        } else {
            node.value = value;
            node.prev.next = node.next;
            node.next.prev = node.prev;
        }

        node.next = this.head.next;
        node.prev = this.head;

        this.head.next.prev = node;
        this.head.next = node;

        if (this.size > this.capacity) {
            this.evict();
        }
    }

    private evict() {
        this.size--;

        const node = this.tail.prev;

        node.prev.next = node.next;
        node.next.prev = node.prev;

        node.prev = null;
        node.next = null;

        this.data.delete(node.key);
    }
}

function maxPoints(points: number[][]): number {
    let res = 1;

    for (let i = 0; i < points.length; i++) {
        const count = new Map();
        const point1 = points[i];
        for (let j = i + 1; j < points.length; j++) {
            const point2 = points[j];
            let slope;
            if (point2[0] === point1[0]) {
                slope = Number.MAX_SAFE_INTEGER;
            } else {
                slope = (point2[1] - point1[1]) / (point2[0] - point1[0]);
            }
            !count.has(slope)
                ? count.set(slope, 2)
                : count.set(slope, count.get(slope) + 1);

            res = Math.max(res, count.get(slope));
        }
    }
    return res;
}

function evalRPN(tokens: string[]): number {
    const stack: number[] = [];

    tokens.forEach((token) => {
        if (token === '+') {
            stack.push(Number(stack.pop()) + Number(stack.pop()));
        } else if (token === '-') {
            const a = Number(stack.pop());
            const b = Number(stack.pop());
            stack.push(b - a);
        } else if (token === '/') {
            const a = Number(stack.pop());
            const b = Number(stack.pop());
            stack.push(Math.trunc(b / a));
        } else if (token === '*') {
            stack.push(Number(stack.pop()) * Number(stack.pop()));
        } else {
            stack.push(Number(token));
        }
    });

    return stack[0];
}

function maxProduct(nums: number[]): number {
    let res = Math.max(...nums);
    let curMax = 1;
    let curMin = 1;

    for (const n of nums) {
        if (n === 0) {
            curMin = 1;
            curMax = 1;
            continue;
        }

        let temp = curMax * n;
        curMax = Math.max(n * curMax, n * curMin, n);
        curMin = Math.min(temp, n * curMin, n);
        res = Math.max(res, curMax);
    }

    return res;
}

function findMin(nums: number[]): number {
    let left: number = 0;
    let right: number = nums.length - 1;
    while (right > left) {
        let midIdx: number = Math.floor((left + right) / 2);
        if (nums[midIdx] > nums[right]) {
            left = midIdx + 1;
        } else {
            right = midIdx;
        }
    }
    return nums[left];
}

class MinStack {
    stack: number[];
    minstack: number[];

    constructor() {
        this.stack = [];
        this.minstack = [];
    }

    push(val: number): void {
        this.stack.push(val);
        if (
            val < this.minstack[this.minstack.length - 1] ||
            this.minstack.length === 0
        ) {
            this.minstack.push(val);
        } else {
            this.minstack.push(this.minstack[this.minstack.length - 1]);
        }
    }

    pop(): void {
        this.stack.pop();
        this.minstack.pop();
    }

    top(): number {
        return this.stack[this.stack.length - 1];
    }

    getMin(): number {
        return this.minstack[this.minstack.length - 1];
    }
}

