function decodeString(s: string): string {
    let stack: string[] = [];

    for (let char of s) {
        if (char !== ']') {
            stack.push(char);
        } else {
            let substr: string = '';
            while (stack[stack.length - 1] !== '[') {
                substr = stack.pop() + substr;
            }
            stack.pop();

            let multiplier: string = '';
            while (
                stack.length !== 0 &&
                Number.isInteger(+stack[stack.length - 1])
            ) {
                multiplier = stack.pop() + multiplier;
            }

            stack.push(substr.repeat(+multiplier));
        }
    }
    return stack.join('');
}

function removeKdigits(num: string, k: number): string {
    let stack: string[] = [];
    for (let ch of num) {
        while (k > 0 && stack.length > 0 && stack[stack.length - 1] > ch) {
            k--;
            stack.pop();
        }
        stack.push(ch);
    }

    let x = 0;
    while (true) {
        if (stack[x] !== '0') {
            break;
        }
        x++;
    }
    stack = stack.slice(x, stack.length - k);
    let res = stack.join('');
    return res ? res : '0';
}

/**
 * Breath First Search implementation
 * @param matrix
 * @param queue
 * @param visited
 */
const bfs = (
    matrix: number[][],
    queue: number[][],
    visited: boolean[][],
): void => {
    let m = matrix.length,
        n = matrix[0].length;
    let directions = [
        [1, 0],
        [-1, 0],
        [0, 1],
        [0, -1],
    ];

    while (queue.length > 0) {
        const [qCordx, qCordy] = queue.shift()!;
        for (let dir of directions) {
            const x = qCordx + dir[0],
                y = qCordy + dir[1];
            if (
                !(
                    x < 0 ||
                    y < 0 ||
                    x >= m ||
                    y >= n ||
                    visited[x][y] ||
                    matrix[x][y] < matrix[qCordx][qCordy]
                )
            ) {
                visited[x][y] = true;
                queue.push([x, y]);
            }
        }
    }
};

