function pacificAtlantic(heights: number[][]): number[][] {
    const ROWS = heights.length,
        COLS = heights[0].length;
    let pacific: boolean[][] = createMatrix(ROWS, COLS);
    let atlantic: boolean[][] = createMatrix(ROWS, COLS);
    let pacQueue: number[][] = [];
    let atlQueue: number[][] = [];
    let results: number[][] = [];

    // Set as 'true' Pacific edges
    for (let i = 0; i < ROWS; i++) {
        pacific[i][0] = true;
        atlantic[i][COLS - 1] = true;
        atlQueue.push([i, COLS - 1]);
        pacQueue.push([i, 0]);
    }
    // Set as 'true' atlantic edges
    for (let j = 0; j < COLS; j++) {
        pacific[0][j] = true;
        atlantic[ROWS - 1][j] = true;
        atlQueue.push([ROWS - 1, j]);
        pacQueue.push([0, j]);
    }

    // BFS
    bfs(heights, pacQueue, pacific);
    bfs(heights, atlQueue, atlantic);

    // Verify intersections
    for (let i = 0; i < ROWS; i++) {
        for (let j = 0; j < COLS; j++) {
            if (pacific[i][j] && atlantic[i][j]) results.push([i, j]);
        }
    }

    return results;
}

function characterReplacement(s: string, k: number): number {
    const charCount = {};

    let max = 0;

    let domChar = 0;

    let l = 0;

    for (let r = 0; r < s.length; r++) {
        if (s[r] in charCount) charCount[s[r]]++;
        else charCount[s[r]] = 1;

        domChar = Math.max(domChar, charCount[s[r]]);

        //if the window size minus the count of the dominant character(number of replacements needed) is bigger than k, invalid
        while (r - l + 1 - domChar > k) {
            charCount[s[l]]--;
            if (charCount[s[l]] === 0) delete charCount[s[l]];
            l++;
        }

        max = Math.max(max, r - l + 1);
    }

    return max;
}

function eraseOverlapIntervals(intervals: number[][]): number {
    intervals.sort(([aStart, aEnd], [bStart, bEnd]) =>
        aEnd !== bEnd ? aEnd - bEnd : aStart - bStart,
    );

    return getGaps(intervals);
}

function getGaps(intervals: number[][]): number {
    let gaps = 0;
    const prev = intervals.shift();

    for (const curr of intervals) {
        const [prevStart, prevEnd] = prev;
        const [currStart, currEnd] = curr;

        const hasGap = prevEnd <= currStart;
        if (!hasGap) {
            continue;
        }

        prev[1] = curr[1];
        gaps++;
    }
    return intervals.length - gaps;
}

