            res.push(w);
        }
    }

    return res;

    function dfs(word: string): boolean {
        for (let i = 1; i < word.length; i++) {
            let prefix = word.slice(0, i);
            let suffix = word.slice(i);

            if (
                (wordSet.has(prefix) && wordSet.has(suffix)) ||
                (wordSet.has(prefix) && dfs(suffix))
            ) {
                return true;
            }
        }

        return false;
    }
}

function findMaxForm(strs: string[], m: number, n: number): number {
    const data = strs.reduce(
        (accum, str) => {
            let zeroes = 0;
            for (let c of str) {
                if (c === '0') zeroes++;
            }
            accum.push([zeroes, str.length - zeroes]);
            return accum;
        },
        [] as [number, number][],
    );

    const dp = Array.from({ length: m + 1 }, () => new Array(n + 1));

    for (let i = 0; i < data.length; i++) {
        const [zeroes, ones] = data[i];

        for (let j = m; j >= 0; j--) {
            for (let k = n; k >= 0; k--) {
                if (dp[j][k] === undefined) dp[j][k] = 0;

                if (j >= zeroes && k >= ones) {
                    dp[j][k] = Math.max(
                        1 + (dp[j - zeroes][k - ones] ?? 0),
                        dp[j][k],
                    );
                }
            }
        }
    }

    return dp[m][n];
}

function findTargetSumWays(nums: number[], target: number): number {
    // key: index, sum till index element, value: number of ways to get to that sum
    const cache = new Map();

    const backTrack = (i, sum) => {
        /*  if we're at the last element + 1 we compare the sum to our target
            if it's true, we've found a way to our sum!
        */
        if (i === nums.length) {
            if (sum === target) {
                return 1;
            }
            return 0;
        }

        // if already index, sum pair exist in our HashMap, we return the memoized result
        if (cache.has(`${i},${sum}`)) {
            return cache.get(`${i},${sum}`);
        }

        // DP: we memoize number of ways of each pair index, sum
        cache.set(
            `${i},${sum}`,
            backTrack(i + 1, sum + nums[i]) + backTrack(i + 1, sum - nums[i]),
        );

        return cache.get(`${i},${sum}`);
    };

    return backTrack(0, 0);
}

/**
 * DP - Bottom Up
 * Time O(N * M) | Space O(M)
 * https://leetcode.com/problems/target-sum/
 * @param {number[]} nums
 * @param {number} target
 * @return {number}
 */
function findTargetSumWays(nums: number[], target: number): number {
    const total = nums.reduce((a, b) => a + b);
    const m = total * 2 + 1;
    let dp = new Array(m).fill(0);
    dp[total] = 1; // base case

    for (let i = 0; i < nums.length; i++) {
        const current = new Array(m);
        const num = nums[i];

        for (let j = 0; j < current.length; j++) {
            const left = dp[j - num] ?? 0;
            const right = dp[j + num] ?? 0;

            current[j] = left + right;
        }
        dp = current;
    }

    return dp[total + target] ?? 0;
}

function nextGreaterElement(nums1: number[], nums2: number[]): number[] {
    const map = {};

    for (let i = 0; i < nums1.length; i++) {
        map[nums1[i]] = i;
    }

    let res = new Array(nums1.length).fill(-1);
    const stack: number[] = [];

    for (let i = 0; i < nums2.length; i++) {
        let cur = nums2[i];
        while (stack.length && cur > stack.at(-1)) {
            let val = stack.pop()!;
            let idx = map[val];
            res[idx] = cur;
        }
        if (map.hasOwnProperty(cur)) {
            stack.push(cur);
        }
    }

    return res;
}

function findMaximizedCapital(
    k: number,
    w: number,
    profits: number[],
    capital: number[],
): number {
    const minCapital = new PriorityQueue({ compare: (a, b) => a[1] - b[1] });
    const maxProfit = new MaxPriorityQueue();
    for (let i = 0; i < profits.length; i++) {
        minCapital.enqueue([profits[i], capital[i]]);
    }

    let profit = w;
    for (let i = 0; i < k; i++) {
        while (!minCapital.isEmpty() && minCapital.front()[1] <= profit) {
            const element = minCapital.dequeue();
            maxProfit.enqueue(element[0]);
        }

        if (maxProfit.isEmpty()) break;
        const { element } = maxProfit.dequeue();
        profit += element;
    }

    return profit;
}

