function isSubtree(root: TreeNode | null, subRoot: TreeNode | null): boolean {
    if (subRoot === null) return true;
    if (root === null) return false;

    if (isSameTree(root, subRoot)) {
        return true;
    }

    let left = isSubtree(root.left, subRoot);
    let right = isSubtree(root.right, subRoot);

    return left || right;
}

function isSameTree(p: TreeNode | null, q: TreeNode | null): boolean {
    if (p === null && q === null) return true;

    if ((p === null && q !== null) || (p !== null && q === null)) return false;

    let leftSame = isSameTree(p.left, q.left);
    let rightSame = isSameTree(p.right, q.right);

    if (p.val === q.val && leftSame && rightSame) {
        return true;
    }

    return false;
}

function canPlaceFlowers(flowerbed: number[], n: number): boolean {
    flowerbed = [0, ...flowerbed, 0];

    for (let i = 1; i < flowerbed.length - 1; i++) {
        if (
            flowerbed[i - 1] == 0 &&
            flowerbed[i + 1] === 0 &&
            flowerbed[i] === 0
        ) {
            flowerbed[i] = 1;
            n -= 1;
        }
    }

    return n <= 0;
}

function leastInterval(tasks: string[], n: number): number {
    const charMap = new Map();
    let maxCharCount = 0;
    let maxChar = tasks[0];

    for (let char of tasks) {
        charMap.set(char, (charMap.get(char) || 0) + 1);
        if (charMap.get(char) > maxCharCount) {
            maxCharCount = charMap.get(char);
            maxChar = char;
        }
    }

    let idleCount = (maxCharCount - 1) * n;

    charMap.forEach((count, char) => {
        // 'return' inside forEach() serve as 'continue'
        if (char === maxChar) {
            return;
        }
        if (count === maxCharCount) {
            idleCount -= count - 1;
        } else {
            idleCount -= count;
        }
    });

    if (idleCount <= 0) {
        return tasks.length;
    }
    return tasks.length + idleCount;
}

function countSubstrings(s: string): number {
    let res = 0;

    for (let i = 0; i < s.length; i++) {
        let l = i;
        let r = i;

        while (l >= 0 && r < s.length && s[l] === s[r]) {
            res += 1;
            l -= 1;
            r += 1;
        }

        l = i;
        r = i + 1;

        while (l >= 0 && r < s.length && s[l] === s[r]) {
            res += 1;
            l -= 1;
            r += 1;
        }
    }

    return res;
}

function findClosestElements(arr: number[], k: number, x: number): number[] {
    let l = 0;
    let r = arr.length - k;

    while (l < r) {
        let m = Math.floor((l + r) / 2);
        if (x - arr[m] > arr[m + k] - x) {
            l = m + 1;
        } else {
            r = m;
        }
    }

    return arr.slice(l, l + k);
}

function checkPossibility(nums: number[]): boolean {
