function trimBST(
    root: TreeNode | null,
    low: number,
    high: number,
): TreeNode | null {
    if (!root) {
        return null;
    }

    if (root.val < low) {
        return trimBST(root.right, low, high);
    }

    if (root.val > high) {
        return trimBST(root.left, low, high);
    }

    root.left = trimBST(root.left, low, high);
    root.right = trimBST(root.right, low, high);

    return root;
}

function checkValidString(s: string): boolean {
    let leftMin = 0;
    let leftMax = 0;

    for (let c of s) {
        if (c === '(') {
            leftMin++;
            leftMax++;
        } else if (c === ')') {
            leftMin--;
            leftMax--;
        } else {
            leftMin--;
            leftMax++;
        }

        if (leftMax < 0) {
            return false;
        }

        if (leftMin < 0) {
            leftMin = 0;
        }
    }

    return leftMin === 0;
}

function validPalindrome(s: string): boolean {
    let l = 0;
    let r = s.length - 1;

    while (l < r) {
        if (s[l] !== s[r]) {
            let skipL = s.slice(l + 1, r + 1);
            let skipR = s.slice(l, r);

            return palinodrome(skipL) || palinodrome(skipR);
        }
        l += 1;
        r -= 1;
    }
    return true;
}

function palinodrome(s: string): boolean {
    let l = 0;
    let r = s.length - 1;

    while (l < r) {
        if (s[l] != s[r]) return false;
        l += 1;
        r -= 1;
    }
    return true;
}

function calPoints(operations: string[]): number {
    const stack: number[] = [];

    for (const op of operations) {
        if (op === '+') {
            stack.push(stack[stack.length - 1] + stack[stack.length - 2]);
        } else if (op === 'D') {
            stack.push(stack[stack.length - 1] * 2);
        } else if (op === 'C') {
            stack.pop();
        } else {
            stack.push(Number(op));
        }
    }

    let res = 0;

    for (const num of stack) {
        res += num;
    }

    return res;
}

function findRedundantConnection(edges: number[][]): number[] {
    let n = edges.length,
        par = new Array(n + 1).fill(0).map((_, index) => index);
    let rank = new Array(n + 1).fill(1);

    function findParent(node: number): number {
        let p = par[node];
        while (p != par[p]) {
            par[p] = par[par[p]];
            p = par[p];
        }
        return p;
    }

    function union(n1: number, n2: number): boolean {
        let p1 = findParent(n1),
            p2 = findParent(n2);
        if (p1 == p2) {
            return false;
        }

        if (rank[p1] > rank[p2]) {
            par[p2] = p1;
            rank[p1] += rank[p2];
        } else {
            par[p1] = p2;
            rank[p2] += rank[p1];
        }
        return true;
    }

    for (let [n1, n2] of edges) {
        if (!union(n1, n2)) {
            return [n1, n2];
        }
    }
}

function maxAreaOfIsland(grid: number[][]): number {
    let directions = [
        [-1, 0],
        [1, 0],
        [0, -1],
        [0, 1],
    ];

    let rows = grid.length;
    let columns = grid[0].length;
    const dfs = (grid, r, c) => {
        let cells = 0;
        if (r < 0 || r >= rows || c < 0 || c >= columns || !grid[r][c])
            return 0;
        grid[r][c] = 0;
        directions.forEach(([dR, dC]) => (cells += dfs(grid, r + dR, c + dC)));

        return cells + 1;
    };

    let max = 0;

    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < columns; j++) {
            max = Math.max(max, dfs(grid, i, j));
        }
    }

    return max;
}

