function pivotIndex(nums: number[]): number {
    let total = nums.reduce((a, b) => a + b);
    let leftSum = 0;

    for (let i = 0; i < nums.length; i++) {
        const rightSum = total - nums[i] - leftSum;

        if (leftSum === rightSum) return i;
        leftSum += nums[i];
    }

    return -1;
}

function asteroidCollision(asteroids: number[]): number[] {
    const stack: number[] = [];

    for (let a of asteroids) {
        while (stack && a < 0 && stack[stack.length - 1] > 0) {
            let diff = a + stack[stack.length - 1];
            if (diff < 0) {
                stack.pop();
            } else if (diff > 0) {
                a = 0;
            } else {
                stack.pop();
                a = 0;
            }
        }
        if (a === 0) continue;
        stack.push(a);
    }

    return stack;
}

function dailyTemperatures(temperatures: number[]): number[] {
    let stack = [];

    let result = new Array(temperatures.length).fill(0);

    for (let i = 0; i < temperatures.length; i++) {
        let currTemp = temperatures[i];

        while (stack.length > 0 && currTemp > stack[stack.length - 1].temp) {
            let { ind } = stack.pop();
            result[ind] = i - ind;
        }

        stack.push({ temp: currTemp, ind: i });
    }

    return result;
}

function networkDelayTime(times: number[][], n: number, k: number): number {
    const adjList = new Map<number, [number, number][]>(
        Array.from({ length: n + 1 }, (_, i) => [i, []]),
    );
    for (let [origin, destination, weight] of times) {
        adjList.get(origin).push([destination, weight]);
    }

    const table = new Array(n + 1);
    for (let i = 1; i < table.length; i++) {
        table[i] = -1;
    }
    table[k] = 0;
    const heap = new MinPriorityQueue({ priority: (a) => a[1] });
    for (let [destination, weight] of adjList.get(k) || []) {
        heap.enqueue([destination, weight]);
    }

    while (!heap.isEmpty()) {
        const { element: minEdge } = heap.dequeue();

        if (table[minEdge[0]] !== -1 && minEdge[1] >= table[minEdge[0]])
            continue;
        table[minEdge[0]] = minEdge[1];

        for (let edge of adjList.get(minEdge[0]) || []) {
            heap.enqueue([edge[0], minEdge[1] + edge[1]]);
        }
    }

    let max = 0;
    for (let i = 1; i < table.length; i++) {
        if (table[i] === -1) return -1;
        max = Math.max(max, table[i]);
    }

    return max;
}

function minCostClimbingStairs(cost: number[]): number {
    cost.push(0);

    for (let i = cost.length - 3; i > -1; i--) {
        cost[i] += Math.min(cost[i + 1], cost[i + 2]);
    }

    return Math.min(cost[0], cost[1]);
}

function swimInWater(grid: number[][]): number {
    const m = grid.length;
    const n = grid[0].length;

    const heap = new MinPriorityQueue({ priority: (a) => a[0] });
    const visited = Array.from({ length: m }, () =>
        Array.from({ length: n }, () => false),
    );
    heap.enqueue([grid[0][0], 0, 0]);

    while (!heap.isEmpty()) {
        const {
            element: [weight, r, c],
        } = heap.dequeue();

        if (r === m - 1 && c === n - 1) return weight;

        const edges = [
            [r - 1, c],
            [r, c + 1],
            [r + 1, c],
            [r, c - 1],
        ];
        for (let [nr, nc] of edges) {
            if (nr < 0 || nr >= m) continue;
            if (nc < 0 || nc >= n) continue;
            if (visited[nr][nc]) continue;

            visited[nr][nc] = true;
            heap.enqueue([Math.max(grid[nr][nc], weight), nr, nc]);
        }
    }

    return 0;
}

function findCheapestPrice(
    n: number,
    flights: number[][],
    src: number,
    dst: number,
    k: number,
): number {
    const adjacencyList = new Map();

    for (let [start, end, cost] of flights) {
        if (adjacencyList.has(start)) {
            adjacencyList.get(start).push([end, cost]);
        } else {
            adjacencyList.set(start, [[end, cost]]);
        }
    }

    const queue = [[0, src, k + 1]];
    const visited = new Map();

    while (queue.length) {
        queue.sort((a, b) => a[0] - b[0]);

        const [cost, city, stops] = queue.shift();
        visited.set(city, stops);

        if (city === dst) {
            return cost;
        }

        if (stops <= 0 || !adjacencyList.has(city)) {
            continue;
        }

        for (let [nextCity, nextCost] of adjacencyList.get(city)) {
            if (visited.has(nextCity) && visited.get(nextCity) >= stops - 1) {
                continue;
            }

            queue.push([cost + nextCost, nextCity, stops - 1]);
        }
    }

    return -1;
}

