function minDiffInBST(root: TreeNode | null): number {
    let prev: TreeNode | null = null;
    let res = Number.MAX_VALUE;

    function dfs(node: TreeNode | null): void {
        if (node) {
            dfs(node.left);

            if (prev) {
                res = Math.min(res, node.val - prev.val);
            }
            prev = node;

            dfs(node.right);
        }
    }

    dfs(root);
    return res;
}

function pushDominoes(dominoes: string): string {
    let res = dominoes.split('');
    while (true) {
        let temp = res.slice();
        let changed = false;
        for (let i = 0; i < res.length; i++) {
            if (res[i + 1] === 'L' && res[i - 1] === 'R' && res[i] === '.') {
                continue;
            } else if (res[i + 1] === 'L' && res[i] === '.') {
                temp[i] = 'L';
                changed = true;
            } else if (res[i - 1] === 'R' && res[i] === '.') {
                temp[i] = 'R';
                changed = true;
            }
        }
        res = temp;
        if (!changed) break;
    }

    return res.join('');
}

function isNStraightHand(hand: number[], groupSize: number): boolean {
    if (hand.length % groupSize) {
        return false;
    }

    let count = {};
    for (let n in hand) {
        if (!count.hasOwnProperty(hand[n])) {
            count[hand[n]] = 0;
        }

        count[hand[n]]++;
    }

    let sortUniqHand = [...new Set(hand)].sort((a, b) => b - a);
    while (sortUniqHand.length > 0) {
        let first = sortUniqHand[sortUniqHand.length - 1];
        for (let i = first; i < first + groupSize; i++) {
            if (!count.hasOwnProperty(i)) {
                return false;
            }

            count[i]--;
            if (count[i] === 0) {
                if (i !== sortUniqHand[sortUniqHand.length - 1]) {
                    return false;
                }

                sortUniqHand.pop();
            }
        }
    }
    return true;
}

function carFleet(target: number, position: number[], speed: number[]): number {
    const combined = position
        .map((item, index) => {
            return [item, speed[index]];
        })
        .sort((a, b) => a[0] - b[0]);

    const stack: number[] = [];

    for (let i = combined.length - 1; i > -1; i--) {
        const p = combined[i][0];
        const s = combined[i][1];

        stack.push((target - p) / s);

        if (
            stack.length >= 2 &&
            stack[stack.length - 1] <= stack[stack.length - 2]
        ) {
            stack.pop();
        }
    }

    return stack.length;
}

function minEatingSpeed(piles: number[], h: number): number {
    let l = 1;
    let r = Math.max(...piles);
    let res = r;

    while (l <= r) {
        let k = Math.floor((l + r) / 2);
        let hours = 0;
        for (const p of piles) {
            hours += Math.ceil(p / k);
        }
        if (hours <= h) {
            res = Math.min(res, k);
            r = k - 1;
        } else {
            l = k + 1;
        }
    }

    return res;
}

function middleNode(head: ListNode | null): ListNode | null {
