function numRescueBoats(people: number[], limit: number): number {
    people.sort((a, b) => a - b);

    let res = 0;
    let l = 0;
    let r = people.length - 1;

    while (l <= r) {
        let remain = limit - people[r];
        r -= 1;
        res += 1;
        if (l <= r && remain >= people[l]) {
            l += 1;
        }
    }
    return res;
}

class FreqStack {
    cnt: Map<number, number>;
    maxCnt: number;
    stacks: Map<number, number[]>;
    constructor() {
        this.cnt = new Map();
        this.maxCnt = 0;
        this.stacks = new Map();
    }

    push(val: number): void {
        let valCnt: number = 1 + (this.cnt.get(val) || 0);
        this.cnt.set(val, valCnt);

        if (valCnt > this.maxCnt) {
            this.maxCnt = valCnt;
            this.stacks.set(valCnt, []);
        }
        this.stacks.get(valCnt)?.push(val);
    }

    pop(): number {
        let res: number = this.stacks.get(this.maxCnt)?.pop()!;
        this.cnt.set(res, this.cnt.get(res)! - 1);

        if (this.stacks.get(this.maxCnt)?.length == 0) {
            this.maxCnt -= 1;
        }

        return res;
    }
}

class StockSpanner {
    private stack: { price: number; spanDays: number }[];

    constructor() {
        this.stack = [];
    }

    next(price: number): number {
        let span = 1;

        while (
            this.stack.length > 0 &&
            this.stack[this.stack.length - 1].price <= price
        ) {
            span += this.stack[this.stack.length - 1].spanDays;
            this.stack.pop();
        }

        this.stack.push({ price, spanDays: span });
        return span;
    }
}

