function totalFruit(fruits: number[]): number {
    let count = new Map();
    let [left, total, res] = [0, 0, 0];

    for (let fruit of fruits) {
        count.set(fruit, (count.get(fruit) || 0) + 1);
        total++;

        while (count.size > 2) {
            let f = fruits[left];
            count.set(f, count.get(f) - 1);
            total--;
            left++;
            if (!count.get(f)) {
                count.delete(f);
            }
        }

        res = Math.max(res, total);
    }

    return res;
}

function maxSubarraySumCircular(nums: number[]): number {
    let [globalMax, globalMin] = [nums[0], nums[0]];
    let [currentMax, currentMin] = [0, 0];
    let total = 0;

    for (let num of nums) {
        currentMax = Math.max(num, currentMax + num);
        currentMin = Math.min(num, currentMin + num);
        total += num;
        globalMax = Math.max(globalMax, currentMax);
        globalMin = Math.min(globalMin, currentMin);
    }

    return globalMax > 0 ? Math.max(globalMax, total - globalMin) : globalMax;
}

