function sortedSquares(nums: number[]): number[] {
    let left: number = 0;
    let right: number = nums.length - 1;

    const answer: number[] = [];

    while (left <= right) {
        const leftSqr = nums[left] * nums[left];
        const rightSqr = nums[right] * nums[right];

        if (leftSqr > rightSqr) {
            answer.push(leftSqr);
            left++;
        } else {
            answer.push(rightSqr);
            right--;
        }
    }
    return answer.reverse();
}

//use an hashmap for keys, then each key will have an array (increasing order because of problem rules) of timestamps with values (represented as javascript objects {key, value})
class TimeMap {
    public hash: {};

    constructor() {
        this.hash = {};
    }

    set(key: string, value: string, timestamp: number): void {
        if (key in this.hash) {
            this.hash[key].push({ timestamp, value });
        } else this.hash[key] = [{ timestamp, value }];
    }

    get(key: string, timestamp: number): string {
        //if key is not in the hashmap there are no timestamps nor values, return ""
        if (!(key in this.hash)) return '';
        let timestamps = this.hash[key];
        //if there are no timestamps or the first timestamp is already bigger than target timestamp(they are sorted so all next ones will big too), return ""
        if (timestamps.length === 0 || timestamps[0].timestamp > timestamp)
            return '';

        //starts from the first timestamp as closest
        let closest = timestamps[0];

        let [l, r] = [0, timestamps.length - 1];

        //binary search, but
        while (l <= r) {
            let mid = Math.floor((l + r) / 2);

            if (timestamps[mid].timestamp === timestamp)
                return timestamps[mid].value;
            //update closest if mid element's timestamp is still less than target timestamp
            if (timestamps[mid].timestamp < timestamp)
                closest = timestamps[mid];

            if (timestamps[mid].timestamp < timestamp) l = mid + 1;
            if (timestamps[mid].timestamp > timestamp) r = mid - 1;
        }

        return closest.value;
    }
}

function mincostTickets(days: number[], costs: number[]): number {
    const dp = new Array(days.length + 1);
    dp[dp.length - 1] = 0;

    for (let j = dp.length - 2; j >= 0; j--) {
        const a = costs[0] + dp[j + 1];

        let d = j;
        do {
            d++;
        } while (days[d] < days[j] + 7 && d < dp.length);
        const b = costs[1] + dp[d];

        d = j;
        do {
            d++;
        } while (days[d] < days[j] + 30 && d < dp.length);
        const c = costs[2] + dp[d];
        dp[j] = Math.min(a, b, c);
    }

    return dp[0];
}

function addToArrayForm(num: number[], k: number): number[] {
    num.reverse();
    let i = 0;

    while (k > 0) {
        const digit = k % 10;
        i < num.length ? (num[i] += digit) : num.push(digit);

        const carry = Math.floor(num[i] / 10);
        num[i] %= 10;

        k = Math.floor(k / 10);
        k += carry;
        i++;
    }

    return num.reverse();
}

function orangesRotting(grid: number[][]): number {
    let [ROWS, COLS, time, fresh, q] = [grid.length, grid[0].length, 0, 0, []];
    let dirs = [
        [0, 1],
        [0, -1],
        [1, 0],
        [-1, 0],
    ];

    // count fresh oranges and add rotten oranges to queue
    for (let i = 0; i < ROWS; i++) {
        for (let j = 0; j < COLS; j++) {
            if (grid[i][j] === 1) {
                fresh++;
            }
            if (grid[i][j] === 2) {
                q.push([i, j]);
            }
        }
    }

    while (q.length > 0 && fresh > 0) {
        let qLen = q.length;

        for (let rot = 0; rot < qLen; rot++) {
            let [row, col] = q.shift();

            for (let dir of dirs) {
                let [r, c] = [row + dir[0], col + dir[1]];

                if (
                    r < 0 ||
                    r >= ROWS ||
                    c < 0 ||
                    c >= COLS ||
                    grid[r][c] !== 1
                ) {
                    continue;
                }

                grid[r][c] = 2;
                fresh--;
                q.push([r, c]);
            }
        }
        time++;
    }
    return fresh > 0 ? -1 : time;
}

