        heap.insert(stone1 - stone2);
    }

    return heap.peek();
}

function lastStoneWeightII(stones: number[]): number {
    const sum = stones.reduce((a, b) => a + b);
    const target = Math.ceil(sum / 2);

    let dp = Array.from({ length: sum + 1 }, (_, i) => {
        return Math.abs(i - (sum - i));
    });

    for (let i = 0; i < stones.length; i++) {
        const current: number[] = Array.from({ length: sum + 1 });
        for (let j = current.length - 1; j >= 0; j--) {
            if (j >= target) {
                current[j] = Math.abs(j - (sum - j));
            } else {
                current[j] = Math.min(dp[j], dp[j + stones[i]]);
            }
        }

        dp = current;
    }

    return dp[0];
}

function gcdOfStrings(str1: string, str2: string): string {
    let [len1, len2] = [str1.length, str2.length];

    function isDivisor(l: number): boolean {
        if (len1 % l || len2 % l) {
            return false;
        }

        let [f1, f2] = [Math.floor(len1 / l), Math.floor(len2 / l)];

        return (
            str1.slice(0, l).repeat(f1) == str1 &&
            str1.slice(0, l).repeat(f2) == str2
        );
    }

    for (let l = Math.min(len1, len2); l > 0; l--) {
        if (isDivisor(l)) {
            return str1.slice(0, l);
        }
    }

    return '';
}

