function goodNodes(root: TreeNode | null): number {
    // edge case
    if (root === null) return 0;

    //keep track of the count
    let count = 0;

    const dfs = (root, max) => {
        //if value is bigger than max of path, then it is a good node
        if (root.val >= max) count++;

        //extend search to children if not null with updated max(takes current node in consideration too)
        if (root.left !== null) dfs(root.left, Math.max(max, root.val));
        if (root.right !== null) dfs(root.right, Math.max(max, root.val));
    };

    //starts with negative max value, because min value is just the smaller positive value in javascript
    dfs(root, -Number.MAX_VALUE);

    return count;
}

function checkIfPrerequisite(
    numCourses: number,
    prerequisites: number[][],
    queries: number[][],
): boolean[] {
    const adjList = new Map<number, number[]>(
        Array.from({ length: numCourses }, (_, i) => [i, []]),
    );
    for (let [a, b] of prerequisites) {
        adjList.get(b).push(a);
    }

    const cache = new Map<number, Set<number>>();
    function dfs(node: number) {
        if (!cache.has(node)) {
            cache.set(node, new Set());

            for (let target of adjList.get(node)) {
                const result = dfs(target);
                for (let v of result) {
                    cache.get(node).add(v);
                }
            }
        }

        cache.get(node).add(node);
        return cache.get(node);
    }

    for (let i = 0; i < numCourses; i++) {
        dfs(i);
    }

    return queries.map(([a, b]) => cache.get(b).has(a));
}

function shuffle(nums: number[], n: number): number[] {
    for (let i = 0; i < n; i++) {
        nums[i] = nums[i] << 10;
        nums[i] = nums[i] | nums[i + n];
    }

    let j = 2 * n - 1;

    for (let i = n - 1; i > -1; i--) {
        let y = nums[i] & (2 ** 10 - 1);
        let x = nums[i] >> 10;
        nums[j] = y;
        nums[j - 1] = x;
        j -= 2;
    }

    return nums;
}

