function maxFrequency(nums: number[], k: number): number {
    const sortedNums: number[] = nums.sort((a: number, b: number) => a - b);

    let maxLength: number = 0;

    let currentSum: number = 0;
    let leftWindow: number = 0;
    for (
        let rightWindow: number = 0;
        rightWindow < sortedNums.length;
        rightWindow++
    ) {
        const currentLength: number = rightWindow - leftWindow + 1;
        const rightNum: number = sortedNums[rightWindow];
        currentSum += rightNum;

        if (currentSum + k >= rightNum * currentLength) {
            maxLength = currentLength;
        } else {
            const leftNum = sortedNums[leftWindow];
            currentSum -= leftNum;
            leftWindow++;
        }
    }
    return maxLength;
}

function minFlips(s: string): number {
    if (!s || s.length < 1) return 0;

    const initialLen = s.length;
    if (initialLen % 2 === 1) s += s;

    let evenCmp = 0;
    let oddCmp = 0;
    let result = Infinity;
    let end = 0;
    let start = 0;

    while (end < s.length) {
        if (end % 2 !== Number(s[end])) evenCmp++;
        if ((end % 2 ^ 1) !== Number(s[end])) oddCmp++;

        if (end >= initialLen) {
            if (start % 2 !== Number(s[start])) evenCmp--;
            if ((start % 2 ^ 1) !== Number(s[start])) oddCmp--;
            start++;
        }

        if (end >= initialLen - 1) {
            result = Math.min(evenCmp, oddCmp, result);
        }
        end++;
    }

    return result;
}

function mergeTriplets(triplets: number[][], target: number[]): boolean {
